<?php
declare(strict_types=1);

/**
 * Render the customer-safe printable payment request.
 *
 * Only the saved request snapshot and Company Profile are accepted here. This
 * keeps the public document presentation-only and prevents accidental exposure
 * of workflow fields such as internal_notes or customer_response.
 */
function documents_render_public_payment_request(?array $request, array $company): string
{
    $visible = is_array($request) && !empty($request['visibility_to_customer']);
    $payable = $visible && documents_payment_request_is_publicly_payable($request);
    $e = static fn($value): string => htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8');
    $inr = static fn($value): string => '₹' . number_format((float) $value, 2);
    $companyName = (string) (($company['brand_name'] ?? '') ?: ($company['company_name'] ?? 'Dakshayani Enterprises'));
    $logoPath = documents_normalize_public_asset_path($company['logo_path'] ?? '');
    $contact = array_values(array_filter([(string) ($company['phone_primary'] ?? ''), (string) ($company['email_primary'] ?? ''), (string) ($company['website'] ?? '')], static fn($v): bool => trim($v) !== ''));
    $address = array_values(array_filter([(string) ($company['address_line'] ?? ''), trim((string) ($company['city'] ?? '') . ' ' . (string) ($company['district'] ?? '')), trim((string) ($company['state'] ?? '') . ' ' . (string) ($company['pin'] ?? ''))], static fn($v): bool => trim($v) !== ''));
    $instructions = $payable ? documents_payment_instructions($request, $company) : ['upi' => null, 'bank' => []];
    $project = $visible ? (float) ($request['quotation_amount'] ?? 0) : 0.0;
    $paid = $visible ? (float) ($request['amount_paid_against_request'] ?? 0) : 0.0;
    $outstanding = $visible ? (float) ($request['outstanding_against_request'] ?? 0) : 0.0;

    ob_start();
    ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title><?= $visible ? 'Payment Request ' . $e($request['id'] ?? '') : 'Payment request unavailable' ?></title>
<style>:root{--teal:#0f766e;--ink:#12302b;--muted:#64748b;--line:#dbe7e3;--soft:#f4faf8}*{box-sizing:border-box}body{margin:0;background:#eef6f4;color:var(--ink);font:14px/1.55 Arial,Helvetica,sans-serif}.toolbar{max-width:900px;margin:18px auto 0;text-align:right}.btn{display:inline-block;border:0;border-radius:999px;background:var(--teal);color:#fff;padding:10px 18px;font-weight:700;text-decoration:none;cursor:pointer}.sheet{max-width:900px;margin:18px auto 30px;background:#fff;border:1px solid var(--line);box-shadow:0 18px 48px #0f302b24}.brand{display:grid;grid-template-columns:1fr auto;gap:24px;padding:28px 32px;background:linear-gradient(135deg,#0b4f49,#0f766e);color:#fff}.brand-main{display:flex;gap:16px;align-items:center}.logo-box{display:grid;place-items:center;min-width:92px;min-height:72px;padding:8px;background:#fff;border-radius:14px}.logo-box img{display:block;max-width:150px;max-height:58px}.logo-fallback{font-size:28px;font-weight:900;color:var(--teal)}.brand h1{margin:0;font-size:25px}.brand p{margin:4px 0 0;color:#dff7f1}.brand-meta{text-align:right;font-size:12px;color:#e6fffb}.content{padding:30px 32px}.doc-title{display:flex;justify-content:space-between;gap:20px;margin-bottom:22px}.doc-title h2{margin:0;font-size:34px}.ref-card,.card,.metric{border:1px solid var(--line);border-radius:14px}.ref-card{min-width:240px;padding:13px 16px;background:var(--soft)}.label{display:block;color:var(--muted);font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.value{font-weight:800}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:16px 0}.card{padding:16px}.summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:18px 0}.metric{padding:14px;background:#f8fbfa}.metric strong{display:block;margin-top:4px;font-size:17px}.metric.requested{grid-column:span 2;background:linear-gradient(135deg,#ecfdf5,#fff7ed);border:2px solid #9bd8ca}.metric.requested strong{font-size:30px;color:var(--teal)}.section-title{margin:24px 0 8px;color:var(--teal);font-size:15px;text-transform:uppercase}.instructions{display:grid;gap:10px}.instruction-row{display:flex;justify-content:space-between;gap:12px;overflow-wrap:anywhere}.copy-action{border:1px solid var(--teal);background:#fff;color:var(--teal);border-radius:7px;padding:3px 8px;cursor:pointer}.closing{margin-top:26px;padding-top:18px;border-top:1px solid var(--line)}.footer{padding:14px 32px;color:var(--muted);font-size:12px;background:#f8fbfa;border-top:1px solid var(--line);display:flex;justify-content:space-between}.unavailable{text-align:center;padding:55px 30px}.toast{position:fixed;bottom:18px;left:50%;transform:translateX(-50%);background:var(--ink);color:#fff;padding:8px 16px;border-radius:99px;display:none}@media print{body{background:#fff}.toolbar{display:none}.sheet{margin:0;max-width:none;border:0;box-shadow:none}.brand{print-color-adjust:exact;-webkit-print-color-adjust:exact}}@media(max-width:720px){.brand,.grid,.summary{grid-template-columns:1fr}.doc-title{display:block}.brand-meta{text-align:left}.metric.requested{grid-column:auto}}</style></head><body>
<?php if (!$visible): ?><main class="sheet unavailable"><h1>Payment request unavailable</h1><p>This link is invalid or this request is not available to customers.</p><p>Please contact <?= $e($companyName) ?> for assistance.</p></main>
<?php else: ?><div class="toolbar"><button class="btn" type="button" onclick="window.print()">Print Payment Request</button></div><main class="sheet"><header class="brand"><div class="brand-main"><div class="logo-box"><?php if ($logoPath !== ''): ?><img src="<?= $e($logoPath) ?>" alt="<?= $e($companyName) ?> logo"><?php else: ?><span class="logo-fallback">DE</span><?php endif; ?></div><div><h1><?= $e($companyName) ?></h1><p><?= $e(implode(' • ', $contact)) ?></p><p><?= $e(implode(', ', $address)) ?></p></div></div><div class="brand-meta"><strong>Not a receipt</strong><br>Receipts remain the source of truth for payment received.</div></header><section class="content"><div class="doc-title"><div><span class="label">Customer payment document</span><h2>Payment Request</h2></div><div class="ref-card"><span class="label">Request No.</span><div class="value"><?= $e($request['id'] ?? '') ?></div><span class="label">Request Date</span><div><?= $e(substr((string) ($request['created_at'] ?? ''), 0, 10)) ?></div></div></div>
<div class="grid"><div class="card"><span class="label">Customer Details</span><strong><?= $e($request['customer_name'] ?? '') ?></strong><br><?= $e($request['customer_mobile'] ?? '') ?></div><div class="card"><span class="label">Project / Quotation Reference</span><strong><?= $e($request['quotation_id'] ?? '') ?></strong><br>Status: <?= $e(ucwords(str_replace('_', ' ', (string) ($request['status'] ?? 'draft')))) ?></div></div>
<div class="summary"><div class="metric"><span class="label">Total Project Amount</span><strong><?= $e($inr($project)) ?></strong></div><div class="metric"><span class="label">Paid So Far</span><strong><?= $e($inr($paid)) ?></strong></div><div class="metric"><span class="label">Outstanding</span><strong><?= $e($inr($outstanding)) ?></strong></div><div class="metric requested"><span class="label">Requested Amount</span><strong><?= $e($inr($request['amount_requested'] ?? 0)) ?></strong></div><div class="metric"><span class="label">Due Date</span><strong><?= $e(($request['due_date'] ?? '') ?: 'As discussed') ?></strong></div></div>
<h3 class="section-title">Reason / Payment Purpose</h3><div class="card"><?= $e(documents_payment_request_reason_label($request)) ?></div><?php if (trim((string) ($request['message'] ?? '')) !== ''): ?><h3 class="section-title">Message</h3><div class="card"><?= nl2br($e($request['message'])) ?></div><?php endif; ?><h3 class="section-title">Payment Instructions</h3><div class="card instructions"><?php if (!$payable): ?><strong>Online payment is not available for this request.</strong><?php else: ?><?php if (is_array($instructions['upi'] ?? null)): $upi = $instructions['upi']; ?><a class="btn" href="<?= $e($upi['uri']) ?>"><?= $e($upi['label']) ?></a><div class="instruction-row"><span>UPI ID: <strong><?= $e($upi['id']) ?></strong></span><button class="copy-action" type="button" data-copy="<?= $e($upi['id']) ?>">Copy</button></div><?php endif; ?><?php if (($instructions['bank'] ?? []) !== []): ?><strong>Bank transfer</strong><?php foreach ($instructions['bank'] as $field): ?><div class="instruction-row"><span><?= $e($field['label']) ?>: <strong><?= $e($field['value']) ?></strong></span><button class="copy-action" type="button" data-copy="<?= $e($field['value']) ?>">Copy</button></div><?php endforeach; ?><?php endif; ?><?php endif; ?></div><div class="closing"><p>Kindly make the payment so that we can proceed with the next stage of work.</p><p><strong>Regards,<br><?= $e($companyName) ?></strong></p></div></section><footer class="footer"><span>Not a receipt</span><span>Payment Request <?= $e($request['id'] ?? '') ?></span></footer></main><div id="toast" class="toast" role="status">Copied</div><script>document.querySelectorAll('[data-copy]').forEach(function(b){b.addEventListener('click',function(){var v=b.getAttribute('data-copy')||'',done=function(){var t=document.getElementById('toast');t.style.display='block';setTimeout(function(){t.style.display='none'},1200)};if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(v).then(done)}else{var x=document.createElement('textarea');x.value=v;document.body.appendChild(x);x.select();document.execCommand('copy');x.remove();done()}})});</script><?php endif; ?></body></html><?php
    return (string) ob_get_clean();
}
